<?php
require_once __DIR__.'/../Services/Auditoria.php';require_once __DIR__.'/Producto.php';require_once __DIR__.'/Rol.php';
class Bitacora {
 private $db;
 public function __construct(PDO $db){$this->db=$db;}
 public function catalogos(){
  $users=$this->db->query("SELECT id,nombre,activo FROM usuarios UNION ALL SELECT b.usuario_id,MAX(b.usuario_nombre),0 FROM bitacora_actividad b LEFT JOIN usuarios u ON u.id=b.usuario_id WHERE b.usuario_id IS NOT NULL AND u.id IS NULL GROUP BY b.usuario_id ORDER BY nombre,id")->fetchAll();
  $types=array();foreach(Auditoria::tipos() as $k=>$v)$types[]=array('id'=>$k,'nombre'=>$v);$today=(new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')));$permissions=array_column(Rol::catalogo(),'nombre','clave');return array('permisos'=>$permissions,'usuarios'=>$users,'operaciones'=>$types,'desde'=>$today->modify('-6 days')->format('Y-m-d'),'hasta'=>$today->format('Y-m-d'));
 }
 private function filtros(array $f){
  $zone=new DateTimeZone('America/Mexico_City');$today=new DateTimeImmutable('today',$zone);$dates=array();foreach(array('desde','hasta') as $k){$s=isset($f[$k])?$f[$k]:($k==='desde'?$today->modify('-6 days')->format('Y-m-d'):$today->format('Y-m-d'));$d=is_string($s)?DateTimeImmutable::createFromFormat('!Y-m-d',$s,$zone):false;if(!$d||$d->format('Y-m-d')!==$s||$s<'2023-01-01'||$s>'9998-12-31')throw new HttpError('Elige fechas válidas a partir de 2023.');$dates[$k]=$d;}$days=(int)$dates['desde']->diff($dates['hasta'])->format('%r%a');if($days<0||$days>365)throw new HttpError('Elige un rango de hasta 366 días, con inicio anterior o igual al fin.');
  $uid=Producto::identificador(isset($f['usuario_id'])&&$f['usuario_id']!==''?$f['usuario_id']:null,true);$type=isset($f['tipo'])?$f['tipo']:'';if(!is_string($type)||($type!==''&&!isset(Auditoria::tipos()[$type])))throw new HttpError('Selecciona una operación válida.');return array('desde'=>$dates['desde']->format('Y-m-d'),'hasta'=>$dates['hasta']->format('Y-m-d'),'inicio'=>$dates['desde']->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),'fin'=>$dates['hasta']->modify('+1 day')->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s'),'usuario_id'=>$uid,'tipo'=>$type);
 }
 public function listar(array $input){
  $f=$this->filtros($input);$hash=hash('sha256',json_encode($f));$sql='SELECT id,usuario_id,usuario_nombre,usuario_login,tipo,referencia,resumen,historico,UNIX_TIMESTAMP(creado_en) fecha_unix FROM bitacora_actividad WHERE creado_en>=? AND creado_en<?';$args=array($f['inicio'],$f['fin']);if($f['usuario_id']!==null){$sql.=' AND usuario_id=?';$args[]=$f['usuario_id'];}if($f['tipo']!==''){$sql.=' AND tipo=?';$args[]=$f['tipo'];}
  if(isset($input['antes_de'])&&$input['antes_de']!==''){$cursor=$input['antes_de'];if(!is_string($cursor)||strlen($cursor)>400||!preg_match('/^[a-zA-Z0-9_-]+$/D',$cursor))throw new HttpError('La página no es válida. Vuelve a consultar.');$c=json_decode(base64_decode(strtr($cursor,'-_','+/'),true),true);if(!is_array($c)||!isset($c['fecha'],$c['id'],$c['f'])||!is_int($c['fecha'])||$c['fecha']<0||$c['fecha']>253402300799||!is_string($c['f'])||!hash_equals($hash,$c['f']))throw new HttpError('Los filtros cambiaron. Vuelve a consultar desde el inicio.');$id=Producto::identificador($c['id']);$sql.=' AND (creado_en< FROM_UNIXTIME(?) OR (creado_en=FROM_UNIXTIME(?) AND id<?))';array_push($args,$c['fecha'],$c['fecha'],$id);}
  $sql.=' ORDER BY creado_en DESC,id DESC LIMIT 31';$zone=$this->db->query('SELECT @@SESSION.time_zone')->fetchColumn();try{$this->db->exec("SET time_zone='+00:00'");$q=$this->db->prepare($sql);$q->execute($args);$rows=$q->fetchAll();}finally{$this->db->exec('SET SESSION time_zone='.$this->db->quote($zone));}$more=count($rows)>30;if($more)array_pop($rows);$next=null;if($more){$last=$rows[count($rows)-1];$next=rtrim(strtr(base64_encode(json_encode(array('fecha'=>(int)$last['fecha_unix'],'id'=>(string)$last['id'],'f'=>$hash))),'+/','-_'),'=');}return array('registros'=>$rows,'siguiente'=>$next,'filtros'=>array_intersect_key($f,array_flip(array('desde','hasta','usuario_id','tipo'))));
 }
 public function detalle($id){$id=Producto::identificador($id);$q=$this->db->prepare('SELECT id,usuario_id,usuario_nombre,usuario_login,tipo,referencia,resumen,historico,UNIX_TIMESTAMP(creado_en) fecha_unix,detalle FROM bitacora_actividad WHERE id=?');$q->execute(array($id));$r=$q->fetch();if(!$r)throw new HttpError('Registro de actividad no encontrado.',404);$r['detalle']=json_decode($r['detalle'],true);return $r;}
}
